-- Stacko_New_Images.xlsx: 24 library entries (scripts/import/image-batch.py). Idempotent.
do $$
declare v_brand uuid := (select id from public.brands where name = 'Stacko' order by created_at limit 1);
begin
  if v_brand is null then raise exception 'brand not found'; end if;
  insert into public.library_items (brand_id, code, kind, status, title, collection, aspect, prompt, use_for,
    when_to_use, fits_posts, notes, placeholders)
  select v_brand, i.code, i.kind, i.status, left(i.title, 300), i.collection, i.aspect, i.prompt, i.use_for,
    i.when_to_use, i.fits_posts, i.notes, i.placeholders
  from jsonb_to_recordset($lib$[{"code": "BG-56", "kind": "background", "status": "approved", "title": "Dark field of tiny dots forming slow waves", "collection": "Background", "aspect": "4:5 vertical", "prompt": "Abstract background: an endless field of tiny glowing dots arranged on a grid, gently rising and falling like slow waves, seen from a low angle so it fades into darkness at the top. The dots are soft blue, a few in the centre glow brighter teal #2EF2EE. Composition: waves in the lower half, the top 55% almost empty dark navy. Style: 3D render, shallow depth of field, very clean. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Text-led dark posts: big numbers, polls, quotes, carousel inner slides", "when_to_use": "Any time (reusable)", "fits_posts": "\"3 warehouses. 1 spreadsheet.\" style posts; IDEA-001, IDEA-003, IDEA-004, IDEA-066, IDEA-071, IDEA-077", "notes": "Theme: Dark; Renamed from BG-01 (Stacko_New_Images.xlsx)", "placeholders": null}, {"code": "BG-57", "kind": "background", "status": "approved", "title": "Bright paper studio with soft shadows of boxes", "collection": "Background", "aspect": "4:5 vertical", "prompt": "Abstract light background: a seamless pale blue-white paper studio (#F4F8FA) with soft, long shadows of a few cardboard boxes falling in from the bottom-right corner (the boxes themselves are out of frame), gentle morning light. Composition: shadows only in the bottom-right third, everything else calm and empty. Style: minimal photoreal studio shot. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Light posts with cards on top: myths, checklists, glossary, how-to", "when_to_use": "Any time (reusable)", "fits_posts": "Light educational posts; IDEA-005, IDEA-006, IDEA-007, IDEA-008, IDEA-009, IDEA-010, IDEA-035, IDEA-037, IDEA-039, IDEA-044, IDEA-051, IDEA-055, IDEA-061, IDEA-069, IDEA-075, IDEA-081, IDEA-085", "notes": "Theme: Light; Renamed from BG-02 (Stacko_New_Images.xlsx)", "placeholders": null}, {"code": "BG-58", "kind": "background", "status": "approved", "title": "Night aerial of a coastal city with glowing route lines", "collection": "Background", "aspect": "4:5 vertical", "prompt": "Abstract top-down aerial view of a Mediterranean coastal city at night, rendered in dark navy and deep blue like a stylised satellite image, with three thin glowing teal #2EF2EE lines tracing roads between districts, the sea a smooth darker area on the left. Composition: the lines cross the lower 60%; the top 40% is darker and calm. Style: stylised 3D map render, subtle grain. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Map and route posts, transfers, multi-branch, LinkedIn covers", "when_to_use": "Any time (reusable)", "fits_posts": "\"Every route, in one view\"; IDEA-001, IDEA-002, IDEA-012, IDEA-013, IDEA-033, IDEA-048, IDEA-086", "notes": "Theme: Dark; Renamed from BG-03 (Stacko_New_Images.xlsx)", "placeholders": null}, {"code": "BG-59", "kind": "background", "status": "approved", "title": "Frosted glass panels with blurred blue light", "collection": "Background", "aspect": "4:5 vertical", "prompt": "Abstract background: layered frosted glass panels at slight angles, soft out-of-focus blue and teal light glowing behind them, clean and airy, very light overall (mostly white and pale blue). Composition: brightest glow in the lower-right; top-left calm for text. Style: 3D render, soft depth of field. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Behind UI cards, feature lists, product announcements", "when_to_use": "Any time (reusable)", "fits_posts": "Feature spotlights; IDEA-011, IDEA-014, IDEA-015, IDEA-016, IDEA-017", "notes": "Theme: Light; Renamed from BG-04 (Stacko_New_Images.xlsx)", "placeholders": null}, {"code": "BG-60", "kind": "background", "status": "approved", "title": "Macro texture of corrugated cardboard in blue light", "collection": "Background", "aspect": "4:5 vertical", "prompt": "Extreme macro photograph of the cut edge of corrugated cardboard, the wavy inner layer visible, lit from the side with cool blue light so it looks moody and premium, deep navy shadows. Composition: texture diagonally across the lower half, top half falls into soft darkness. Style: macro photography, 100mm lens. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Quote cards, founder quotes, testimonials, announcements", "when_to_use": "Any time (reusable)", "fits_posts": "\"Why we built Stacko\" quote; IDEA-013, IDEA-018, IDEA-019, IDEA-020, IDEA-021, IDEA-022, IDEA-023, IDEA-024", "notes": "Theme: Dark; Renamed from BG-05 (Stacko_New_Images.xlsx)", "placeholders": null}, {"code": "BG-61", "kind": "background", "status": "approved", "title": "Vertical gradient sky with a few floating boxes", "collection": "Background", "aspect": "9:16 vertical", "prompt": "Vertical background: a calm gradient from deep navy at the top to soft blue at the bottom, with five small cardboard boxes floating weightlessly at different depths in the lower third, slightly blurred, one box faintly glowing teal from inside. Composition: the top two thirds empty for text and stickers. Style: 3D render, soft focus. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Instagram Stories and story covers (polls, links, reposts)", "when_to_use": "Any time (reusable)", "fits_posts": "Story backgrounds; IDEA-025, IDEA-026, IDEA-027, IDEA-028, IDEA-029, IDEA-078", "notes": "Theme: Dark; Renamed from BG-06 (Stacko_New_Images.xlsx)", "placeholders": null}, {"code": "SC-01", "kind": "post_image", "status": "approved", "title": "White van on a winding Lebanese mountain road at blue hour", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A plain white delivery van driving up a winding mountain road in Lebanon at blue hour, pine trees and terraced hills, village lights in the valley below, the van's headlights on, slight motion blur. Composition: road curves through the lower 55%; leave the top 40% as clean deep-blue sky. Style: photoreal, drone shot from above and behind. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Road transfers between branches, ETA posts, WHY-2 follow-ups", "when_to_use": "Nov–Dec 2026", "fits_posts": "\"Beirut → Zahle. You'll know when it lands.\"; IDEA-001, IDEA-030, IDEA-031, IDEA-032, IDEA-033", "notes": "Theme: Dark", "placeholders": null}, {"code": "SC-02", "kind": "post_image", "status": "approved", "title": "Delivery van on a Dubai highway with skyline at dusk", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A plain white delivery van on a wide Dubai highway at dusk, the city skyline softly blurred in the background, long light trails from traffic, cool blue sky. Composition: van in the lower-left third; leave the top 40% as clean sky. Style: photoreal editorial, long exposure, low angle. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Gulf audience posts, UAE branches, \"From Beirut to Dubai\"", "when_to_use": "Nov 2026 (Gulf push) and any time", "fits_posts": "\"Your Dubai branch, on the same map\"; IDEA-034, IDEA-035, IDEA-036, IDEA-037", "notes": "Theme: Dark", "placeholders": null}, {"code": "SC-03", "kind": "post_image", "status": "approved", "title": "Owner on his sofa at night checking his phone", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A Lebanese business owner, man in his early 40s, short dark hair, trimmed beard, grey sweater, sitting on a sofa in a dim living room at night, holding his phone and looking at it, the phone screen facing the camera, only a small lamp and the phone lighting the scene. Composition: man in the right half; leave the left 45% dark and calm. Style: photoreal, 50mm, cinematic. Screens: any phone or tablet screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Peace of mind, alerts, \"Know before the shelf is empty\"", "when_to_use": "Any time", "fits_posts": "\"11 PM. Do you know what's in stock?\"; IDEA-038, IDEA-039, IDEA-040, IDEA-041", "notes": "Theme: Dark", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "SC-04", "kind": "post_image", "status": "approved", "title": "Driver's hands logging on a phone inside a truck cab", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "Close-up inside a delivery truck cab: a driver's hands holding a smartphone above the steering wheel, the phone screen facing the camera, the windshield showing a blurred city street at early morning. Composition: phone in the centre-right, large; the top 30% is the soft blurred windshield. Style: photoreal, 35mm, shallow depth of field. Screens: any phone or tablet screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Staff logging, \"one message\", driver stories", "when_to_use": "Any time", "fits_posts": "\"Logged before the engine starts\"; IDEA-042, IDEA-043, IDEA-044, IDEA-045", "notes": "Theme: Dark", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "SC-05", "kind": "post_image", "status": "approved", "title": "Shop shelf with one empty gap where a product should be", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A clean, modern retail shelf in a bright electronics shop, neatly lined with identical plain white product boxes, with one obvious empty gap in the middle row. Composition: shelf across the lower 60%, gap slightly right of centre; leave the top 35% as calm blurred shop wall. Style: photoreal, straight-on, soft daylight. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Out-of-stock pain, lost sales, HOW-2 style revenue posts", "when_to_use": "Any time; strong before White Friday", "fits_posts": "\"The empty spot costs more than the stock.\"; IDEA-001, IDEA-046, IDEA-047, IDEA-048, IDEA-049", "notes": "Theme: Light", "placeholders": null}, {"code": "SC-06", "kind": "post_image", "status": "approved", "title": "Morning coffee and a phone on a desk at sunrise", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "A minimal desk by a large window at early morning: a white coffee cup with a little steam, a smartphone lying face up beside it with its screen facing up and blank, a closed notebook. Soft cool morning light, a calm city view blurred outside. Composition: objects in the lower 45%, top half calm window light. Style: photoreal, top-down 45° angle. Screens: any phone or tablet screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "\"8 AM stock check\", daily routine, owner habits", "when_to_use": "Weekday mornings", "fits_posts": "\"Your 8 AM check takes 10 seconds now\"; IDEA-050, IDEA-051, IDEA-052", "notes": "Theme: Light", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "SC-07", "kind": "post_image", "status": "approved", "title": "Team hands around a tablet on a meeting table (top view)", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "Top-down view of a light wooden meeting table: four people's hands around a tablet in the centre, one pointing at the screen, the tablet screen facing up and blank white, two coffee cups and a notebook around it. Composition: tablet in the centre-lower area; leave the top 30% of the table clear. Style: photoreal flat lay, soft daylight. Screens: any phone or tablet screen is blank, evenly lit white, facing the camera. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "\"One shared picture\", roles, team posts, LinkedIn", "when_to_use": "Any time", "fits_posts": "\"Everyone sees the same stock\"; IDEA-053, IDEA-054, IDEA-055", "notes": "Theme: Light", "placeholders": "Blank white phone/tablet screen → place a real Stacko screen (assets/screens/)"}, {"code": "SC-08", "kind": "post_image", "status": "approved", "title": "Container doors opening on neatly packed boxes with teal light", "collection": "Scene", "aspect": "4:5 vertical", "prompt": "The doors of a shipping container swinging open at night, revealing neatly stacked cardboard boxes inside, a soft teal #2EF2EE light glowing from deep inside the container onto the boxes, cool blue port lights outside. Composition: open doors centred in the lower 60%; leave the top 35% as dark night sky. Style: photoreal, cinematic, eye level. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Imports arrived, receiving, \"Shipment landed\" posts", "when_to_use": "Any time", "fits_posts": "\"30 days at sea. Logged in seconds on arrival.\"; IDEA-001, IDEA-056, IDEA-057, IDEA-058", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-01", "kind": "post_image", "status": "approved", "title": "Hourglass filled with tiny boxes instead of sand", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A tall glass hourglass on a dark glossy surface, filled with hundreds of tiny cardboard boxes instead of sand, the boxes falling through the narrow middle, a soft teal glow at its base. Composition: hourglass centred in the lower 65%; top 30% clean dark navy. Style: photoreal 3D product render, studio light. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Time lost to manual counts, ETA posts, \"hours, not days\"", "when_to_use": "Any time", "fits_posts": "\"How many hours does your stock count take?\"; IDEA-059, IDEA-060, IDEA-061", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-02", "kind": "post_image", "status": "approved", "title": "Magnifying glass revealing one glowing box in a pile", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A large magnifying glass hovering over a big pile of identical plain cardboard boxes; inside the lens one box glows softly teal from within, the rest stay dark blue-grey. Composition: pile across the lower half, lens slightly right of centre; top 35% clean. Style: photoreal 3D render, dramatic studio light. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Search, \"how much do we have and where?\", finding stock", "when_to_use": "Any time", "fits_posts": "\"Find any item in seconds\"; IDEA-062, IDEA-063, IDEA-064", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-03", "kind": "post_image", "status": "approved", "title": "Chess board where the pieces are small boxes", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A glossy dark chess board seen from a low angle, the chess pieces replaced by small cardboard boxes of different heights, one box in the centre lit by a soft teal spotlight. Composition: board in the lower 55%; top 40% dark and empty. Style: photoreal 3D render, shallow depth of field. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Planning, owner/strategy posts, LinkedIn thought pieces", "when_to_use": "Any time", "fits_posts": "\"Move your stock like a strategy, not a guess\"; IDEA-065, IDEA-066, IDEA-067", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-04", "kind": "post_image", "status": "approved", "title": "Cardboard jigsaw puzzle with the last piece glowing", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A large jigsaw puzzle made of plain cardboard lying on a pale blue-white surface, almost complete, with the last piece hovering just above its gap and glowing softly teal at its edges. Composition: puzzle in the lower 60%, angled; top 35% calm. Style: photoreal top-down at 30°, soft daylight. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Missing data, \"the missing piece\", integrations, audit trail", "when_to_use": "Any time", "fits_posts": "\"Stock data with no missing pieces\"; IDEA-068, IDEA-069", "notes": "Theme: Light", "placeholders": null}, {"code": "OB-05", "kind": "post_image", "status": "approved", "title": "Paper notebook turning into a glowing map", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "An open paper notebook with handwritten-looking grey scribble lines (not readable) on the left page; on the right page the lines lift off the paper and turn into a glowing 3D teal route map with tiny warehouse blocks, floating above the page. Composition: notebook in the lower 60%; top 35% dark navy. Style: photoreal mixed with clean 3D, cinematic. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Before/after in one image, transformation, onboarding", "when_to_use": "Any time", "fits_posts": "\"From notebook to map, in one week\"; IDEA-070, IDEA-071, IDEA-072", "notes": "Theme: Dark", "placeholders": null}, {"code": "OB-06", "kind": "post_image", "status": "approved", "title": "Tall wobbling tower of boxes about to fall", "collection": "Concept", "aspect": "4:5 vertical", "prompt": "A tall, narrow tower of mismatched cardboard boxes balanced like a game of stacking blocks, leaning dangerously to one side, one box sliding out, on a pale blue studio floor. Composition: tower slightly left of centre, rising to about 70% of the frame height; empty space on the right. Style: photoreal 3D render, soft studio light. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Risk of no system, growth pains, meme-ish brand posts", "when_to_use": "Any time", "fits_posts": "\"Growing fast? Your stock system shouldn't wobble.\"; IDEA-073, IDEA-074, IDEA-075", "notes": "Theme: Light", "placeholders": null}, {"code": "SE-01", "kind": "post_image", "status": "approved", "title": "White Friday rush: boxes and a shopping cart in motion", "collection": "Seasonal", "aspect": "4:5 vertical", "prompt": "A shopping cart overflowing with plain cardboard boxes rolling fast down a dark glossy floor, motion blur and light streaks behind it, soft teal glow under the cart. Composition: cart in the lower-centre; top 40% dark and empty. Style: photoreal 3D render, dynamic low angle. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "\"Be ready for the rush\" post + story", "when_to_use": "Publish 20–26 Nov 2026 (White Friday is 27 Nov)", "fits_posts": "\"Is your stock ready for White Friday?\"; IDEA-076, IDEA-077, IDEA-078, IDEA-079", "notes": "Theme: Dark", "placeholders": null}, {"code": "SE-02", "kind": "post_image", "status": "approved", "title": "Year-end stocktake: clipboard, boxes and a December night window", "collection": "Seasonal", "aspect": "4:5 vertical", "prompt": "A quiet stockroom corner at night in December: a clipboard with blank paper on top of a few stacked boxes, a window behind showing a cold blue night with a few soft snowflake-like bokeh lights. Composition: boxes and clipboard in the lower-right; left and top calm. Style: photoreal, 35mm, moody. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Year-end count tips, \"close the year with clean numbers\"", "when_to_use": "Publish 1–20 Dec 2026", "fits_posts": "\"Year-end count without the all-nighter\"; IDEA-080, IDEA-081, IDEA-082, IDEA-083", "notes": "Theme: Dark", "placeholders": null}, {"code": "SE-03", "kind": "post_image", "status": "approved", "title": "New Year: boxes with cool teal sparkler light", "collection": "Seasonal", "aspect": "4:5 vertical", "prompt": "Three neatly stacked cardboard boxes on a dark glossy surface, with thin teal and white sparkler trails swirling around them like light painting, a few soft bokeh lights in the background. Composition: boxes in the lower-centre; top 40% dark. Style: long-exposure light-painting photo, cool tones only. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "New Year 2027 greeting from Stacko", "when_to_use": "Publish 31 Dec 2026 – 1 Jan 2027", "fits_posts": "\"New year, clear stock\"; IDEA-084, IDEA-085", "notes": "Theme: Dark", "placeholders": null}, {"code": "SE-04", "kind": "post_image", "status": "approved", "title": "Ramadan: lantern glowing on top of stacked boxes", "collection": "Seasonal", "aspect": "4:5 vertical", "prompt": "A traditional Ramadan lantern (fanous) with intricate metal patterns, glowing with soft teal-white light, placed on top of a neat stack of cardboard boxes, a crescent moon visible through a dark blue window behind. Composition: lantern and boxes in the lower 60%, slightly right; top-left calm. Style: photoreal, cinematic, cool palette only. Light & colour: cool blue tones, deep navy #0E2440 shadows, soft blue #79C0DE fills, teal #2EF2EE accent only where stated; no orange, yellow or red. Avoid: any text, letters, numbers, logos, labels, signage, watermarks, UI content, extra fingers.", "use_for": "Ramadan Kareem greeting (EN + AR)", "when_to_use": "Publish at the start of Ramadan (around 8 Feb 2027)", "fits_posts": "\"Ramadan Kareem\" / \"رمضان كريم\"; IDEA-086, IDEA-087, IDEA-088", "notes": "Theme: Dark", "placeholders": null}]$lib$::jsonb) as i(code text, kind text, status text, title text,
    collection text, aspect text, prompt text, use_for text, when_to_use text, fits_posts text, notes text,
    placeholders text)
  on conflict (brand_id, code) do nothing;
